begin
  select data into cur from public.sp_store where id = 'main';
  if cur is null then insert into public.sp_store(id, data) values ('main', nw) on conflict (id) do update set data = excluded.data; return; end if;
  cur := cur || jsonb_build_object('v', 2, 'builder', nw->'builder',
    'sections', coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(cur->'sections','[]'::jsonb)) x where coalesce((x->>'demo')::boolean,false) = false and not (x->>'id' = any (select y->>'id' from jsonb_array_elements(nw->'sections') y))), '[]'::jsonb) || (nw->'sections'),
    'products', coalesce((select jsonb_agg(x) from jsonb_array_elements(coalesce(cur->'products','[]'::jsonb)) x where coalesce((x->>'demo')::boolean,false) = false and not (x->>'id' = any (select y->>'id' from jsonb_array_elements(nw->'products') y))), '[]'::jsonb) || (nw->'products'));
  update public.sp_store set data = cur where id = 'main';
end $do$;
